[metadata] {"type": "create", "filePath": "/workspace/repo/codex-rs/tui/src/chatwidget/warnings.rs", "content": "//! Deduplication of warning messages surfaced in the conversation history.
//!
//! Some warnings are emitted repeatedly for the same underlying condition (for
//! example, a model whose metadata could not be resolved emits a fallback
//! warning on every turn). Displaying each occurrence clutters the transcript,
//! so [`WarningDisplayState`] tracks which model-specific warnings have already
//! been shown and suppresses later duplicates.

use std::collections::HashSet;

/// Prefix of the model metadata fallback warning, preceding the model slug.
const MODEL_METADATA_PREFIX: &str = "Model metadata for `";
/// Suffix of the model metadata fallback warning, following the model slug.
const MODEL_METADATA_SUFFIX: &str =
    "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

/// Tracks which warnings have already been displayed, enabling deduplication of
/// model-specific metadata warnings.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs whose metadata fallback warning has already been shown.
    seen_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Decide whether `message` should be added to the chat history.
    ///
    /// For the model metadata fallback warning, returns `true` the first time a
    /// given slug is seen and `false` for every subsequent occurrence of the
    /// same slug. All other warnings are always displayed.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match extract_metadata_slug(message) {
            Some(slug) => self.seen_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// Extract the model slug from a metadata fallback warning, if `message`
/// matches the exact pattern.
fn extract_metadata_slug(message: &str) -> Option<&str> {
    message
        .strip_prefix(MODEL_METADATA_PREFIX)?
        .strip_suffix(MODEL_METADATA_SUFFIX)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn metadata_warning(slug: &str) -> String {
        format!(
            "Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues."
        )
    }

    #[test]
    fn metadata_warning_shown_once_per_slug() {
        let mut state = WarningDisplayState::default();
        let warning = metadata_warning("unknown-model");
        assert!(state.should_display(&warning));
        assert!(!state.should_display(&warning));
        // A different slug is still shown once.
        let other = metadata_warning("other-model");
        assert!(state.should_display(&other));
        assert!(!state.should_display(&other));
    }

    #[test]
    fn generic_warnings_always_shown() {
        let mut state = WarningDisplayState::default();
        let warning = "Something else happened.";
        assert!(state.should_display(warning));
        assert!(state.should_display(warning));
    }
}
